const go=id=>{ const t=el(id); if(t) t.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'}); };
let active=null; const ans={}, touched={};
const TASKS=[
 {k:'ceil',model:1,q:t2('Find the ceiling in the ENBR METAR: tap the group that sets it.','Finn skydekket (ceiling) i METAR-en fra ENBR: trykk på gruppen som bestemmer det.'),setup:()=>{ if(S.k!=='mBR'){ setTab('dec'); load('mBR'); } },
  check:()=>{ if(S.k!=='mBR') return {ok:0,m:t2('Load the ENBR METAR (Example reports → METAR → ENBR).','Last inn METAR-en fra ENBR (Eksempelrapporter → METAR → ENBR).')}; const x=D.toks[S.sel];
    if(!x) return {ok:0,m:t2('Tap a cloud group in the report.','Trykk på en skygruppe i rapporten.')};
    if(x.t==='BKN008') return {ok:1,m:t2('Yes: BKN008 is the lowest broken layer, 800 ft above the aerodrome. With 4,000 m visibility that is below VFR minima in the control zone: special VFR at best.','Ja: BKN008 er laveste brutte lag, 800 ft over flyplassen. Med 4000 m sikt er det under VFR-minima i kontrollsonen: i beste fall spesiell VFR.')};
    if(x.t==='OVC015') return {ok:0,m:t2('OVC015 is a ceiling layer, but not the lowest one.','OVC015 er et skydekkelag, men ikke det laveste.')};
    return {ok:0,m:t2(`${x.t} is not a cloud layer that makes the ceiling. Look for BKN or OVC.`,`${x.t} er ikke et skylag som gir skydekke. Se etter BKN eller OVC.`)}; }},
 {k:'enbr',q:t2('Is ENBR legal for a VFR arrival at 14Z per this TAF?','Er ENBR lovlig for en VFR-ankomst kl. 14Z ifølge denne TAF-en?'),
  opts:[t2('Yes: the main part says 9999 SCT020 BKN040','Ja: hoveddelen sier 9999 SCT020 BKN040'),t2('No: from 14Z the ceiling is BKN008, special VFR at best, and PROB30 TEMPO even gives IFR','Nei: fra 14Z er skydekket BKN008, i beste fall spesiell VFR, og PROB30 TEMPO gir til og med IFR'),t2('Yes, because BECMG has not started yet at 14Z','Ja, fordi BECMG ikke har startet ennå kl. 14Z'),t2('Only if the TEMPO 1206/1212 is ignored','Bare hvis TEMPO 1206/1212 ses bort fra')],c:1,
  e:()=>[t2('Right. BECMG 1212/1214 is complete at 14Z: 6000 RA BKN008 OVC015, ceiling 800 ft (SVFR). PROB30 TEMPO 1214/1220 adds 2000 +RA BKN005: IFR possible.','Riktig. BECMG 1212/1214 er ferdig kl. 14Z: 6000 RA BKN008 OVC015, skydekke 800 ft (SVFR). PROB30 TEMPO 1214/1220 legger til 2000 +RA BKN005: IFR mulig.'),t2('Not quite. A BECMG applies fully from the end of its period: from 14Z the ceiling is BKN008 (800 ft), below the 1,500 ft VFR minimum. PROB30 TEMPO 2000 +RA BKN005 is IFR.','Ikke helt. En BECMG gjelder fullt fra slutten av perioden: fra 14Z er skydekket BKN008 (800 ft), under VFR-minimum på 1500 ft. PROB30 TEMPO 2000 +RA BKN005 er IFR.')],
  show:()=>{ setTab('dec'); load('tBR'); S.t=Date.UTC(2026,10,12,14,0); syncTime(); moveCur(); }},
 {k:'gm',model:1,q:t2('ENGM TAF: from what time is the prevailing forecast VFR? Move the time cursor there.','TAF for ENGM: fra hvilket tidspunkt er rådende prognose VFR? Flytt tidsmarkøren dit.'),setup:()=>{ if(S.k!=='tGM'){ setTab('dec'); load('tGM'); } },
  check:()=>{ if(S.k!=='tGM') return {ok:0,m:t2('Load the ENGM TAF (Example reports → TAF → ENGM).','Last inn TAF-en for ENGM (Eksempelrapporter → TAF → ENGM).')}; const t=S.t, v=Date.UTC(2026,10,12,12,0);
    if(S.prev==='VFR'&&t>=v&&t<=v+3600e3) return {ok:1,m:t2('Yes: 12:00Z, when BECMG 1210/1212 is complete (9999 NSW SCT015). Until then fog, then BKN004: IFR. Note the TEMPO from 20Z and the PROB40 freezing fog in the early morning.','Ja: 12:00Z, når BECMG 1210/1212 er ferdig (9999 NSW SCT015). Til da tåke, så BKN004: IFR. Legg merke til TEMPO fra 20Z og PROB40 underkjølt tåke tidlig på morgenen.')};
    if(S.prev==='VFR') return {ok:0,m:t2('VFR here, but is it the first time? Go earlier.','VFR her, men er det første gang? Gå tidligere.')};
    return {ok:0,m:t2(`${dhm(new Date(t))}: prevailing ${S.prev}. Go later; a BECMG applies fully from the end of its period.`,`${dhm(new Date(t))}: rådende ${S.prev}. Gå senere; en BECMG gjelder fullt fra slutten av perioden.`)}; }},
 {k:'tempo',q:t2('TEMPO 1212/1218 4000 SHRASN BKN012CB. How long may each spell of these conditions last?','TEMPO 1212/1218 4000 SHRASN BKN012CB. Hvor lenge kan hver periode med disse forholdene vare?'),
  opts:[t2('Less than 1 hour each, together less than half of the 6 hours','Under 1 time hver, til sammen under halvparten av de 6 timene'),t2('The whole 6 hours','Hele de 6 timene'),t2('Up to 2 hours each','Opptil 2 timer hver'),t2('Exactly 30 minutes','Nøyaktig 30 minutter')],c:0,
  e:()=>[t2('Right: TEMPO means temporary fluctuations under 1 hour each, together under half the period.','Riktig: TEMPO betyr midlertidige svingninger under 1 time hver, til sammen under halvparten av perioden.'),t2('Not quite. TEMPO: each spell under 1 hour, in total under half the period. Longer changes would be BECMG or FM.','Ikke helt. TEMPO: hver periode under 1 time, til sammen under halvparten av perioden. Lengre endringer blir BECMG eller FM.')],
  show:()=>{ setTab('dec'); load('tTO'); const i=D.toks.findIndex(x=>x.t==='TEMPO'); if(i>=0){ select(i); timeToGroup(D.toks[i].gi); } }},
 {k:'cavok',q:t2('METAR ENZV … CAVOK … Which of these can still be true?','METAR ENZV … CAVOK … Hva av dette kan likevel stemme?'),
  opts:[t2('SCT060: scattered cloud at 6,000 ft','SCT060: spredte skyer i 6000 ft'),t2('Visibility 8 km','Sikt 8 km'),t2('TCU at 4,000 ft','TCU i 4000 ft'),t2('Light rain','Lett regn')],c:0,
  e:()=>[t2('Right. CAVOK allows cloud at or above 5,000 ft (or the highest MSA) as long as there is no CB or TCU.','Riktig. CAVOK tillater skyer i eller over 5000 ft (eller høyeste MSA) så lenge det ikke er CB eller TCU.'),t2('Not quite. CAVOK needs 10 km or more, no CB/TCU and no significant weather; cloud at or above 5,000 ft (or the highest MSA) is allowed.','Ikke helt. CAVOK krever 10 km eller mer, ingen CB/TCU og ikke noe signifikant vær; skyer i eller over 5000 ft (eller høyeste MSA) er tillatt.')],
  show:()=>{ setTab('dec'); load('mZV'); const i=D.toks.findIndex(x=>x.t==='CAVOK'); if(i>=0) select(i); }},
 {k:'xxx',q:t2('On a Sig Wx chart a CB area is labelled ISOL EMBD CB 280/XXX. What does XXX mean?','På et Sig Wx-kart er et CB-område merket ISOL EMBD CB 280/XXX. Hva betyr XXX?'),
  opts:[t2('The bases are below the chart’s lower level','Basene er under kartets nedre nivå'),t2('The tops are unknown','Toppene er ukjente'),t2('Extreme turbulence','Ekstrem turbulens'),t2('No icing','Ingen ising')],c:0,
  e:()=>[t2('Right. 280 is the top (FL280); XXX means the base is outside the levels the chart covers (here below FL100).','Riktig. 280 er toppen (FL280); XXX betyr at basen er utenfor nivåene kartet dekker (her under FL100).'),t2('Not quite. The pair is top/base: tops FL280, and XXX means the base is outside the chart’s level band.','Ikke helt. Paret er topp/bunn: toppene i FL280, og XXX betyr at basen er utenfor kartets nivåbånd.')],
  show:()=>{ setTab('chart'); S.sym='cb'; drawChart(); chip(); }}];
function drawTasks(){ el('tasks').innerHTML=TASKS.map((t,i)=>`<li class="task" id="task-${t.k}"><span class="n">${L(t2('Task','Oppgave'))} ${i+1}</span><p class="q">${L(t.q)}</p>`+
   (t.model?`<div class="btns"><button type="button" class="btn pri sm" data-go="${t.k}">${L(t2('Do it in the model','Gjør det i modellen'))} ↑</button></div><span class="fb" id="fb-${t.k}"></span>`:'')+
   (t.opts?(()=>{ const a=ans[t.k], e=a!=null?t.e():null; return `<div class="opts">${t.opts.map((o,j)=>`<button type="button" data-t="${t.k}" data-o="${j}" class="${a!=null&&j===t.c?'right':''}${a===j&&j!==t.c?' wrong':''}">${L(o)}</button>`).join('')}</div><span class="fb${a===t.c?' ok':''}">${e?L(e[a===t.c?0:1]):''}</span><div class="btns"><button type="button" class="btn sm" data-show="${t.k}">${L(t2('Show it in the model','Vis i modellen'))} ↑</button></div>`; })():'')+`</li>`).join('');
  live(); drawTbox(); }
function drawTbox(){ const b=el('tbox'); if(!active){ b.hidden=true; return; } const i=TASKS.findIndex(t=>t.k===active);
  b.hidden=false; b.innerHTML=`<span class="k">${L(t2('Task','Oppgave'))} ${i+1}<button type="button" aria-label="${L(t2('Close the task','Lukk oppgaven'))}" id="tclose">×</button></span>${L(TASKS[i].q)}<span class="fb" id="tfb"></span>`;
  el('tclose').onclick=()=>{ active=null; drawTbox(); }; live(); }
function live(){ if(!D) return; TASKS.filter(t=>t.model&&touched[t.k]).forEach(t=>{ const r=t.check(), html=L(r.m); const f=el('fb-'+t.k); if(f){ f.innerHTML=html; f.classList.toggle('ok',!!r.ok); } if(active===t.k){ const g=el('tfb'); if(g){ g.innerHTML=html; g.classList.toggle('ok',!!r.ok); } } }); }
el('tasks').addEventListener('click',e=>{ const gb=e.target.closest('[data-go]'), o=e.target.closest('[data-o]'), sh=e.target.closest('[data-show]');
  if(gb){ active=gb.dataset.go; touched[active]=1; const t=TASKS.find(x=>x.k===active); if(t.setup) t.setup(); drawTbox(); go('explore'); return; }
  if(o){ ans[o.dataset.t]=+o.dataset.o; drawTasks(); return; }
  if(sh){ const t=TASKS.find(x=>x.k===sh.dataset.show); active=null; drawTbox(); t.show(); go('explore'); } });

/* ---------------- quiz ---------------- */
LAB.quiz(el('qbox'),'wxreports',()=>LAB.shuffle([
 {q:t2('A SPECI is…','En SPECI er …'),a:[t2('a special observation issued between routine METARs when the weather changes significantly','en spesialobservasjon som utstedes mellom de faste METAR-ene når været endrer seg vesentlig'),t2('a forecast valid for 2 hours','en prognose som gjelder i 2 timer'),t2('a warning for a whole FIR','et varsel for en hel FIR'),t2('a corrected TAF','en korrigert TAF')],c:0,e:t2('SPECI has the same format as a METAR and is triggered by set change criteria.','SPECI har samme format som en METAR og utløses av fastsatte endringskriterier.')},
 {q:t2('In a METAR, BKN means…','I en METAR betyr BKN …'),a:[t2('5 to 7 oktas','5 til 7 oktas'),t2('3 to 4 oktas','3 til 4 oktas'),t2('8 oktas','8 oktas'),t2('1 to 2 oktas','1 til 2 oktas')],c:0,e:t2('FEW 1–2, SCT 3–4, BKN 5–7, OVC 8 oktas.','FEW 1–2, SCT 3–4, BKN 5–7, OVC 8 oktas.')},
 {q:t2('R27/0550U means…','R27/0550U betyr …'),a:[t2('RVR on runway 27 is 550 m and increasing','RVR på bane 27 er 550 m og økende'),t2('runway 27 is closed until 05:50','bane 27 er stengt til 05:50'),t2('visibility 550 m towards the west','sikt 550 m mot vest'),t2('runway 27 braking action good','bane 27 god bremsevirkning')],c:0,e:t2('U = upward tendency, D = downward, N = no distinct change.','U = økende tendens, D = avtagende, N = ingen tydelig endring.')},
 {q:t2('CAVOK may be used when…','CAVOK kan brukes når …'),a:[t2('visibility is 10 km or more, no cloud below 5,000 ft or the highest MSA, no CB/TCU and no significant weather','sikten er 10 km eller mer, ingen skyer under 5000 ft eller høyeste MSA, ingen CB/TCU og ikke noe signifikant vær'),t2('the sky is completely clear','himmelen er helt klar'),t2('visibility is 5 km or more and the ceiling 1,500 ft','sikten er 5 km eller mer og skydekket 1500 ft'),t2('there is no precipitation','det ikke er nedbør')],c:0,e:t2('Cloud at or above 5,000 ft (or the highest MSA) is allowed if there is no CB or TCU.','Skyer i eller over 5000 ft (eller høyeste MSA) er tillatt hvis det ikke er CB eller TCU.')},
 {q:t2('TAF … BECMG 1012/1014 BKN008 … From when should you expect BKN008?','TAF … BECMG 1012/1014 BKN008 … Fra når må du regne med BKN008?'),a:[t2('At any time from 12Z, and certainly from 14Z','Når som helst fra 12Z, og sikkert fra 14Z'),t2('Only after 14Z','Bare etter 14Z'),t2('Only between 12Z and 14Z','Bare mellom 12Z og 14Z'),t2('From 10Z','Fra 10Z')],c:0,e:t2('The change can happen at any time during the period; the new conditions apply fully from its end.','Endringen kan skje når som helst i perioden; de nye forholdene gjelder fullt fra slutten.')},
 {q:t2('PROB30 TEMPO 1214/1220 TSRA means…','PROB30 TEMPO 1214/1220 TSRA betyr …'),a:[t2('a 30 % probability of temporary thunderstorms with rain between 14 and 20 UTC','30 % sannsynlighet for midlertidige tordenvær med regn mellom kl. 14 og 20 UTC'),t2('thunderstorms for 30 minutes','tordenvær i 30 minutter'),t2('thunderstorms in 30 % of the area','tordenvær i 30 % av området'),t2('30 mm of rain','30 mm regn')],c:0,e:t2('PROB gives the probability (30 or 40 %) of the TEMPO conditions that follow.','PROB gir sannsynligheten (30 eller 40 %) for TEMPO-forholdene som følger.')},
 {q:t2('NOSIG at the end of a METAR means…','NOSIG på slutten av en METAR betyr …'),a:[t2('no significant change is expected in the next 2 hours','ingen vesentlig endring er ventet de neste 2 timene'),t2('no significant weather now','ikke noe signifikant vær nå'),t2('no SIGMET is in force','ingen SIGMET gjelder'),t2('the signal from the sensor is lost','signalet fra sensoren er borte')],c:0,e:t2('NOSIG is a trend forecast, valid 2 hours from the observation time.','NOSIG er et trendvarsel, gyldig 2 timer fra observasjonstiden.')},
 {q:t2('On a Sig Wx chart, ISOL EMBD CB 280/XXX means…','På et Sig Wx-kart betyr ISOL EMBD CB 280/XXX …'),a:[t2('isolated CB embedded in other cloud, tops FL280, bases below the chart’s range','isolerte CB innleiret i andre skyer, toppene FL280, basene under kartets område'),t2('CB from FL280 upwards','CB fra FL280 og oppover'),t2('extreme turbulence at FL280','ekstrem turbulens i FL280'),t2('CB with unknown tops','CB med ukjente topper')],c:0,e:t2('Levels are top/base; XXX = outside the chart’s level band.','Nivåene er topp/bunn; XXX = utenfor kartets nivåbånd.')},
 {q:t2('Which of these is a SIGMET phenomenon?','Hvilket av disse er et SIGMET-fenomen?'),a:[t2('Severe icing','Kraftig ising'),t2('Moderate turbulence','Moderat turbulens'),t2('Light rain','Lett regn'),t2('Isolated cumulus','Isolerte cumulus')],c:0,e:t2('SIGMET covers severe turbulence and icing, embedded/frequent thunderstorms, severe mountain waves, volcanic ash and more. Moderate phenomena can be AIRMET.','SIGMET dekker kraftig turbulens og ising, innleirede/hyppige tordenvær, kraftige fjellbølger, vulkansk aske med mer. Moderate fenomener kan være AIRMET.')},
 {q:t2('The wind direction in a METAR is given relative to…','Vindretningen i en METAR oppgis i forhold til …'),a:[t2('true north','rettvisende nord'),t2('magnetic north','magnetisk nord'),t2('the runway heading','baneretningen'),t2('grid north','kartnord')],c:0,e:t2('METAR and TAF use true direction; ATIS and tower winds for take-off and landing are magnetic.','METAR og TAF bruker rettvisende retning; ATIS og tårnets vind for avgang og landing er magnetisk.')}
]),8);

