LAB.add({},{'Reading the Weather':'Les værmeldingen','Reading the weather':'Les værmeldingen','Birdbird Virtual Lab · Meteorology':'Birdbird Virtual Lab · Meteorologi',
 'Key concepts':'Nøkkelbegreper','Weather report decoder':'Værrapport-dekoder','Try it':'Prøv selv','Key points':'Det viktigste','Test yourself':'Test deg selv','1 · Understand':'1 · Forstå','2 · Explore':'2 · Utforsk','3 · Test yourself':'3 · Test deg selv',
 'Controls':'Kontroller','Conditions':'Forhold','Show':'Vis','Advanced':'Avansert','Example reports':'Eksempelrapporter','Symbols':'Symboler','Paste your own':'Lim inn din egen','Decode':'Avkod','Decoded, group by group':'Avkodet, gruppe for gruppe','Time to check (UTC)':'Tidspunkt å sjekke (UTC)'});
LAB.tx({lead:'METAR, SPECI og TAF, gruppe for gruppe. Velg et norsk eksempel eller lim inn en rapport, trykk på en gruppe for å se hva den betyr, og les en TAF som en tidslinje: hvilke forhold gjelder når du ankommer, og er det VFR? Lær så symbolene på significant weather-kart.',
 goal:'<span class="k">Læringsmål</span>Avkode en METAR og en TAF uten nøkkel, finne skydekket og sikten som gjelder på et gitt tidspunkt, og lese farene på et significant weather-kart.',
 kAll:'Koder, endringsgrupper og varsler i sin helhet'});
on(()=>{
  el('kIntro').textContent=L(t2('The words used in the decoder below. Each card opens an example in the model and points at the group.','Ordene som brukes i dekoderen under. Hvert kort åpner et eksempel i modellen og peker på gruppen.'));
  el('refT').innerHTML=REF_T();
  el('mLead').innerHTML=L(t2('Pick an example from Norwegian aerodromes (or paste your own under Advanced). Every group is underlined by its type: <b>tap one</b> to read it. A TAF is drawn as a <b>timeline</b> over its validity; move the time and see what applies and whether it is VFR. The second tab is a <b>significant weather chart</b> with its symbols.','Velg et eksempel fra norske flyplasser (eller lim inn din egen under Avansert). Hver gruppe er understreket etter type: <b>trykk på en</b> for å lese den. En TAF tegnes som en <b>tidslinje</b> over gyldighetstiden; flytt tiden og se hva som gjelder og om det er VFR. Den andre fanen er et <b>significant weather-kart</b> med symbolene.'));
  el('tryLead').innerHTML=L(t2('Six short tasks. Two you do in the decoder, with live feedback; the others you answer here, then see them in the model.','Seks korte oppgaver. To gjør du i dekoderen, med fortløpende tilbakemelding; de andre svarer du på her, og ser dem så i modellen.'));
  el('take').innerHTML=KEYS.map(x=>`<li>${L(x)}</li>`).join('');
  const m=el('maid'); m.querySelector('.eyebrow').textContent=L(t2('Memory aid','Huskeregel'));
  m.querySelector('h3').innerHTML=L(t2('FM = From now on · BECMG = By the End · TEMPO = Temporary, under an hour','FM = Fra nå av · BECMG = Blir, fullt ved slutten · TEMPO = Tidvis, under en time'));
  m.querySelector('p').innerHTML=L(t2('Read every change group with its time: FM is a clean break at that minute, BECMG is fully in place when its period ends, and TEMPO comes and goes in spells shorter than an hour. PROB30/40 just puts odds in front.','Les hver endringsgruppe med tiden sin: FM er et rent brudd på det minuttet, BECMG er fullt på plass når perioden slutter, og TEMPO kommer og går i perioder kortere enn en time. PROB30/40 setter bare odds foran.'));
  el('dbE').innerHTML=`<span class="k">${L(t2('Deep dive · what the examiner wants you to know','Dypdykk · dette vil sensor at du skal kunne'))}</span>`+[
    t2('<b>Prevailing visibility</b> is the value reached or exceeded over at least half the horizon. When the lowest visibility in one direction is below 1,500 m or below half the prevailing value, it is added with its direction (for example 1200NE).','<b>Dominerende sikt</b> er verdien som nås eller overskrides over minst halve horisonten. Når laveste sikt i én retning er under 1500 m eller under halvparten av den dominerende, legges den til med retning (for eksempel 1200NE).'),
    t2('<b>Cloud heights</b> are above aerodrome elevation in a METAR and TAF, but above mean sea level (or as stated) on area forecasts and Sig Wx charts. Check which before you compare with terrain.','<b>Skyhøyder</b> er over flyplassens høyde i METAR og TAF, men over havet (eller som angitt) i områdeprognoser og Sig Wx-kart. Sjekk hva det er før du sammenligner med terrenget.'),
    t2('<b>Planning with a TAF</b>: the AMC tables for destination and alternate planning say how to treat TEMPO and PROB: a deterioration with persistent conditions in TEMPO must be applied; transient showers or thunderstorms may be disregarded, and so may PROB30/40 TEMPO deteriorations. Your operator’s procedures rule.','<b>Planlegging med TAF</b>: AMC-tabellene for destinasjon og alternativ planlegging sier hvordan TEMPO og PROB behandles: en forverring med vedvarende forhold i TEMPO må legges til grunn; forbigående byger eller tordenvær kan ses bort fra, og det samme kan forverringer i PROB30/40 TEMPO. Operatørens prosedyrer gjelder.'),
    t2('<b>Sig Wx charts</b> come in three bands: low level (surface to FL100 or FL150 in Europe, national), medium (FL100–450) and high (FL250–630, WAFS). They are valid at a fixed time (00, 06, 12, 18 UTC).','<b>Sig Wx-kart</b> finnes i tre bånd: lave nivåer (bakken til FL100 eller FL150 i Europa, nasjonale), midlere (FL100–450) og høye (FL250–630, WAFS). De gjelder ved et fast tidspunkt (00, 06, 12, 18 UTC).')].map(x=>`<p>${L(x)}</p>`).join('');
  el('foot').innerHTML='<b>'+L(t2('Model and limitations.','Modell og begrensninger.'))+'</b> '+L(t2('Training examples, not live or official data: use the official briefing. The reports are invented but realistic Norwegian examples, decoded per ICAO Annex 3 and EU 2017/373; national remarks (RMK) are not decoded. VFR / SVFR / IFR uses the SERA control-zone values (VFR: visibility ≥ 5 km and ceiling ≥ 1,500 ft; SVFR: ≥ 1,500 m and ≥ 600 ft) and ignores other limits such as cloud separation, night and airspace class. The planning notes follow Birdbird’s reading of the AMC tables; the official tables and your operator’s procedures rule. The Sig Wx chart is schematic.','Treningseksempler, ikke aktuelle eller offisielle data: bruk den offisielle briefingen. Rapportene er oppdiktede, men realistiske norske eksempler, avkodet etter ICAO Annex 3 og EU 2017/373; nasjonale merknader (RMK) avkodes ikke. VFR / SVFR / IFR bruker SERA-verdiene for kontrollsone (VFR: sikt ≥ 5 km og skydekke ≥ 1500 ft; SVFR: ≥ 1500 m og ≥ 600 ft) og ser bort fra andre grenser som avstand til skyer, mørke og luftromsklasse. Planleggingsnotatene følger Birdbirds lesing av AMC-tabellene; de offisielle tabellene og operatørens prosedyrer gjelder. Sig Wx-kartet er skjematisk.'));
  el('liveLink').innerHTML=L(t2('For live reports use the <a href="prep.html">Briefing pack</a> or <a href="weather.html">METAR and TAF</a>, and always the official briefing.','For aktuelle rapporter, bruk <a href="prep.html">Briefingpakken</a> eller <a href="weather.html">METAR og TAF</a>, og alltid den offisielle briefingen.'));
  el('pasteHint').textContent=''; el('symHint').textContent=L(t2('Tap a symbol on the chart or in the row under it.','Trykk på et symbol på kartet eller i raden under.'));
  drawTasks();
});

